// ANTI-PATTERN: Car extends Engine
// Why it's bad: A Car is NOT an Engine. A Car shouldn't inherit internal spark plug logic!
class Engine {
    private int horsepower;
    public Engine(int horsepower) { this.horsepower = horsepower; }
    public void start() {
        System.out.println("Engine roaring: " + horsepower + " HP");
    }
}

// CORRECT: Car HAS-AN Engine
class Car {
    private String model;
    private Engine engine; // HAS-A relationship

    public Car(String model, Engine engine) {
        this.model = model;
        this.engine = engine;
    }

    public void drive() {
        System.out.println("Starting trip in " + model);
        engine.start();
    }
}

public class HasAVsIsADemo {
    public static void main(String[] args) {
        Engine v8 = new Engine(450);
        Car mustang = new Car("Mustang GT", v8);
        mustang.drive();
    }
}

