interface SoundDevice {
    void play(String audioFile);
}

class Headset implements SoundDevice {
    public void play(String audioFile) {
        System.out.println("[Headset] Playing private audio: " + audioFile);
    }
}

class BluetoothSpeaker implements SoundDevice {
    public void play(String audioFile) {
        System.out.println("[Speaker] Broadcasting stereo audio: " + audioFile);
    }
}

class Laptop {
    private SoundDevice audioOutput; // Has-A interface

    public Laptop(SoundDevice initialOutput) {
        this.audioOutput = initialOutput;
    }

    public void setAudioOutput(SoundDevice newOutput) {
        this.audioOutput = newOutput;
    }

    public void watchMovie(String movieTitle) {
        System.out.println("Streaming movie: " + movieTitle);
        audioOutput.play(movieTitle + "_soundtrack.mp3");
    }
}

public class SwappableDemo {
    public static void main(String[] args) {
        Laptop laptop = new Laptop(new Headset());
        laptop.watchMovie("Interstellar");

        // Hot-swapping the output device at runtime
        laptop.setAudioOutput(new BluetoothSpeaker());
        laptop.watchMovie("Inception");
    }
}

