class TemperatureSensor {
    private double currentTemp;
    public TemperatureSensor(double currentTemp) {
        this.currentTemp = currentTemp;
    }
    public double readTemp() {
        return currentTemp;
    }
    public void updateTemp(double newTemp) {
        this.currentTemp = newTemp;
    }
}

class Thermostat {
    private String zoneName;
    private double targetTemp;
    private TemperatureSensor sensor;

    public Thermostat(String zoneName, double targetTemp, TemperatureSensor sensor) {
        this.zoneName = zoneName;
        this.targetTemp = targetTemp;
        this.sensor = sensor;
    }

    public void evaluate() {
        double current = sensor.readTemp();
        if (current < targetTemp) {
            System.out.println("[Zone: " + zoneName + "] HEATING ON (Current: " + current + "C, Target: " + targetTemp + "C)");
        } else {
            System.out.println("[Zone: " + zoneName + "] TARGET REACHED (Current: " + current + "C)");
        }
    }
}

public class ThermostatApp {
    public static void main(String[] args) {
        TemperatureSensor sensor = new TemperatureSensor(18.5);
        Thermostat thermostat = new Thermostat("Living Room", 21.0, sensor);
        thermostat.evaluate();
        sensor.updateTemp(21.5);
        thermostat.evaluate();
    }
}

interface PaymentMethod {
    boolean processPayment(double amount);
}

class CreditCardPayment implements PaymentMethod {
    private String maskedCard;
    public CreditCardPayment(String maskedCard) {
        this.maskedCard = maskedCard;
    }
    @Override
    public boolean processPayment(double amount) {
        System.out.println("Charging $" + amount + " to card " + maskedCard);
        return true;
    }
}

class CryptoPayment implements PaymentMethod {
    private String walletAddress;
    public CryptoPayment(String walletAddress) {
        this.walletAddress = walletAddress;
    }
    @Override
    public boolean processPayment(double amount) {
        System.out.println("Sending $" + amount + " in crypto to " + walletAddress);
        return true;
    }
}

class CheckoutTerminal {
    private PaymentMethod currentMethod;
    public CheckoutTerminal(PaymentMethod currentMethod) {
        this.currentMethod = currentMethod;
    }
    public void setPaymentMethod(PaymentMethod currentMethod) {
        this.currentMethod = currentMethod;
    }
    public void checkout(double amount) {
        currentMethod.processPayment(amount);
    }
}

public class PaymentApp {
    public static void main(String[] args) {
        CheckoutTerminal terminal = new CheckoutTerminal(new CreditCardPayment("****-1234"));
        terminal.checkout(99.50);
        terminal.setPaymentMethod(new CryptoPayment("0xABC123"));
        terminal.checkout(450.00);
    }
}

