import java.util.ArrayList;
import java.util.List;

class SimpleList {
    protected List<String> items = new ArrayList<>();
    public void add(String s) { items.add(s); }
    public String removeLast() { return items.isEmpty() ? null : items.remove(items.size() - 1); }
    public void insertAt(int idx, String s) { items.add(idx, s); }
    public int size() { return items.size(); }
}

class SafeStack {
    private SimpleList list = new SimpleList();

    public void push(String s) {
        list.add(s);
    }
    public String pop() {
        return list.removeLast();
    }
    public int size() {
        return list.size();
    }
}

public class StackBugApp {
    public static void main(String[] args) {
        SafeStack stack = new SafeStack();
        stack.push("First");
        stack.push("Second");
        System.out.println("Popped: " + stack.pop());
        System.out.println("Popped: " + stack.pop());
    }
}

interface PowerSource {
    int getChargePercent();
    void drain(int percent);
}

class LithiumBattery implements PowerSource {
    private int charge;
    public LithiumBattery(int charge) {
        this.charge = charge;
    }
    @Override
    public int getChargePercent() {
        return charge;
    }
    @Override
    public void drain(int percent) {
        this.charge = Math.max(0, this.charge - percent);
    }
}

class GpsModule {
    private double lat, lon;
    public GpsModule(double lat, double lon) {
        this.lat = lat;
        this.lon = lon;
    }
    public String getCoordinates() {
        return "(" + lat + ", " + lon + ")";
    }
}

class Quadcopter {
    private String serialNum;
    private PowerSource battery;
    private GpsModule gps;

    public Quadcopter(String serialNum, PowerSource battery, GpsModule gps) {
        this.serialNum = serialNum;
        this.battery = battery;
        this.gps = gps;
    }

    public void flyMission(double destLat, double destLon, int drainCost) {
        System.out.println("[Drone " + serialNum + "] Mission launch from " + gps.getCoordinates());
        battery.drain(drainCost);
        System.out.println("[Drone " + serialNum + "] Mission complete. Remaining battery: " + battery.getChargePercent() + "%");
    }
}

public class DroneApp {
    public static void main(String[] args) {
        PowerSource battery = new LithiumBattery(90);
        GpsModule gps = new GpsModule(37.7749, -122.4194);
        Quadcopter drone = new Quadcopter("DRONE-X9", battery, gps);
        drone.flyMission(37.8000, -122.4000, 25);
    }
}
